\label{sec:opt-means}

\begin{defn}
  \label{def:means}
The \textit{cycle mean} $\lambda(C)$ of a cycle $C$ is its average
edge weight:
\begin{equation}
  \label{eq:means}
  \lambda(C) = \frac{\sum\limits_{e\in C} w(e)}{|C|} = \frac{w(C)}{|C|},
\end{equation}
where $|C| \geq 1$.
\end{defn}

\begin{defn}
  \label{def:opt-means}
The \textit{maximum cycle mean} $\lambda_{max}$ and \textit{minimum
  cycle mean} $\lambda_{min}$ of $G$ are the optimum values of cycle
means over all cycles in $G$. Formally,
\begin{equation}
  \label{eq:opt-means}
  \lambda_{max} = \max\limits_{C\in G} \lambda(C) \quad \text{and}
  \quad \lambda_{min} = \min\limits_{C\in G} \lambda(C).
\end{equation}
\end{defn}
Both are computable efficiently in $O(mn)$ time \citep{Da04}, without
needing to enumerate over all cycles in $G$ explicitly.

Optimum cycle means admit a linear programming formulation. For
example, $\lambda_{min}$ is the maximum $\lambda$ satisfying:
\begin{equation}
  d(v) - d(u) \leq w(u,v) - \lambda, \quad \forall (u,v) \in E,
\end{equation}
where $d(v)$ represents a potential function on nodes. At optimality,
$\lambda=\lambda_{min}$, $d(v)$ can be chosen as the shortest path
distance from an arbitrary source node under the modified weights
$w'(u,v)=w(u,v) - \lambda_{min}$, and $G$ contains no negative cycles
under these modified weights.

\label{sec:basic-results}

The definition of optimum cycle means implies the following
fundamental bounds for any cycle $C$:
\begin{lem}[Basic cycle mean bounds]
\label{lem:basic-bounds}
For any cycle $C$ in $G$:
\begin{equation}
  \label{eq:anycycle1}
  w_{min} \leq \lambda_{min} \leq \frac{w(C)}{|C|} \leq \lambda_{max} \leq w_{max},
\end{equation}
or equivalently,
\begin{equation}
  \label{eq:anycycle2}
  |C|w_{min} \leq |C|\lambda_{min} \leq w(C) \leq |C|\lambda_{max} \leq |C|w_{max}.
\end{equation}
\end{lem}
\begin{proof}
The inequalities $\lambda_{min} \leq \lambda(C) \leq \lambda_{max}$
follow by definition. The outer bounds hold because no cycle mean can
exceed the maximum individual edge weight or be less than the minimum
individual edge weight.
\end{proof}

As mentioned in \S~\ref{sec:graph}, we assume $G$ is strongly
connected, meaning it has at least one cycle. Hence, it is also
guaranteed that $G$ contains at least one min-critical cycle $C_{min}$
and one max-critical cycle $C_{max}$, such that $\lambda_{min} =
\lambda(C_{min})$ and $\lambda_{max} = \lambda(C_{max})$.

\label{sec:longest-basics}

We distinguish two notions of ``longest'' cycle: a \textit{max-weight
cycle} maximizes total weight $w(C)$, while a \textit{max-length cycle}
maximizes edge count $|C|$.

Let $L$ denote a max-weight or a max-length cycle. Trivial bounds on
$w(L)$ can be derived from edge weights alone:
\begin{equation}
  |L|w_{min} \leq w(L) \leq |L|w_{max}.
\end{equation}
However, optimum cycle means provide tighter constraints:
\begin{lem}[Cycle mean bounds for longest cycles]
\label{lem:longest-mean-bounds}
Let $L$ be either a max-weight or max-length cycle in $G$. Then:
\begin{equation}
  \label{eq:longest1}
  \lambda_{min} \leq \lambda(L) \leq \lambda_{max},
\end{equation}
which implies:
\begin{equation}
  \label{eq:longest2}
  |L|\lambda_{min} \leq w(L) \leq |L|\lambda_{max}.
\end{equation}
\end{lem}
\begin{proof}
This is a direct application of Lemma~\ref{lem:basic-bounds} to the
specific cycle $L$.
\end{proof}

While the exact value of $|L|$ is unknown,
Lemma~\ref{lem:longest-mean-bounds} establishes necessary conditions
for the weight of $L$:
\begin{cor}[Sign conditions]
  \label{cor:sign-conditions}
\mbox{}\par
\begin{enumerate}
  \item $\lambda_{min} > 0 \Rightarrow w(L) > 0$.
  \item $\lambda_{max} < 0 \Rightarrow w(L) < 0$.
  \item $\lambda_{min} = 0 \Rightarrow w(L) \geq 0$.
  \item $\lambda_{max} = 0 \Rightarrow w(L_w) = 0$ and $w(L_l) \leq 0$.
\end{enumerate}
\end{cor}

\begin{proof}
Items 1--3 follow from $|L|\lambda_{min} \leq w(L) \leq
|L|\lambda_{max}$. For item 4, $\lambda_{max} = 0$ means every cycle
has non-positive weight, so $w(L_l) \leq 0$; since a zero-mean cycle
exists and $L_w$ maximizes weight, $w(L_w) = 0$. The inequality for
$L_l$ cannot be strengthened to equality: a zero-weight self-loop next
to a two-edge cycle of negative weight gives $\lambda_{max} = 0$ but
$w(L_l) < 0$.
\end{proof}

\label{sec:max-length-case}

Let $L_l$ be a max-length cycle and $\mathcal{C}_{min}$ be the set of
min-critical cycles $C_{min}$ found in $G$. By definition, $|L_l| \geq
|C|$ for all cycles $C$ in $G$.

\begin{lem}[Max-length key inequality]
\label{lem:max-length-key}
$w(L_l) \geq w(C_{min})|L_l| / |C_{min}| = |L_l|\lambda_{min}$.
\end{lem}

\begin{proof}
From $\lambda(L_l) \geq \lambda_{min} = w(C_{min})/|C_{min}|$, multiply
both sides by $|L_l|$.
\end{proof}

\begin{thm}[Max-length cycle bounds]
  \label{thm:max-length}
  We derive the following three cases from
  Lemma~\ref{lem:max-length-key}:
  \begin{enumerate}
    \item If $\lambda_{min} > 0$, then $w(L_l) \geq B_l\lambda_{min}
      \geq \max\limits_{C \in \mathcal{C}_{min}} w(C)$, where $B_l$ is
      the critical witness bound, so that $\mathcal{W} \supseteq
      \mathcal{C}_{min}$.
    \item If $\lambda_{min} < 0$, then no direct comparison between
      $w(L_l)$ and $w(C_{min})$ is possible without knowing $|L_l|$,
      so we fall back to the unconditional bounds in
      Lemma~\ref{lem:longest-mean-bounds}.
    \item If $\lambda_{min} = 0$, $w(L_l) \geq 0$ as shown in
      Corollary~\ref{cor:sign-conditions}.
\end{enumerate}
\end{thm}

\begin{proof}
\mbox{}\par
\begin{itemize}
  \item \textbf{Case 1 ($\lambda_{min} > 0$):} By
    Lemma~\ref{lem:witness}, $|L_l| \geq B_l \geq |C_{min}|$ for every
    $C_{min}$. Since $\lambda_{min} > 0$, multiplying by
    $\lambda_{min}$ yields $|L_l|\lambda_{min} \geq B_l\lambda_{min}
    \geq |C_{min}|\lambda_{min} = w(C_{min})$. By
    Lemma~\ref{lem:max-length-key} and since $C_{min}$ is arbitrary,
    this implies $w(L_l) \geq B_l\lambda_{min} \geq \max\limits_{C \in
      \mathcal{C}_{min}} w(C)$.
  \item \textbf{Case 2 ($\lambda_{min} < 0$):} The inequality $|L_l|
    \geq |C_{min}|$ implies $|L_l|\lambda_{min} \leq
    |C_{min}|\lambda_{min}$. The lower bound weakens, so we rely on
    the general upper bound $w(L_l) \leq |L_l|\lambda_{max}$.
  \item \textbf{Case 3 ($\lambda_{min} = 0$):} Proven above.
\end{itemize}
\end{proof}

\begin{cor}[Length bound for max-length cycles]
  \label{cor:max-length-length-bound}
  Let $B_l$ be the critical witness bound. Without any sign condition,
  \begin{equation}
    |L_l| \geq B_l \geq \max\limits_{C \in \mathcal{C}_{min}} |C|.
  \end{equation}
  When $\lambda_{min} > 0$, this dominates the bound $|L_l| \geq
  \max\limits_{C \in \mathcal{C}_{min}} w(C)/\lambda_{max}$ obtained by
  combining Theorem~\ref{thm:max-length} with
  Lemma~\ref{lem:longest-mean-bounds}.
\end{cor}

\begin{proof}
  The first claim is item 1 of Lemma~\ref{lem:witness}. For the
  second, $w(C)/\lambda_{max} = |C|\lambda_{min}/\lambda_{max} \leq
  |C|$ for every $C \in \mathcal{C}_{min}$, since $0 < \lambda_{min}
  \leq \lambda_{max}$.
\end{proof}

\begin{remark}[Weight shifting]
  \label{rem:weight-shift}
  Subtracting $\lambda_{min}$ from all edge weights yields a
  transformed graph with $\lambda'_{min} = 0$ and $\lambda'_{max} =
  \lambda_{max} - \lambda_{min}$. While this transformation alters the
  max-weight cycle, it preserves the max-length cycle. Applying Case~3
  of Theorem~\ref{thm:max-length} to the transformed graph gives
  $w'(L_l) \geq 0$, which converts back to $w(L_l) \geq
  |L_l|\lambda_{min}$, exactly the unconditional bound from
  Lemma~\ref{lem:longest-mean-bounds}. Corollary~\ref{cor:max-length-length-bound}
  is unaffected, since it depends only on cycle lengths, which the
  shift preserves. This confirms that when $\lambda_{min} \leq 0$,
  the weight-shifting technique cannot improve upon the weight bounds
  from Lemma~\ref{lem:longest-mean-bounds}.
\end{remark}

\label{sec:shortest-results}

Finding the minimum weight directed cycle in a graph without negative
cycles is solvable in $O(nm)$ time \citep{OrSe2017}; with negative
cycles allowed, the problem is NP-hard, since negating all weights
turns it into the max-weight cycle problem. Notably, this
state-of-the-art algorithm explicitly computes $\lambda_{min}$ as a
preprocessing step to reweight the graph
and restrict the search space, empirically confirming that solving the
minimum mean cycle problem is advantageous prior to exact cycle
optimization. Motivated by this connection, we provide the algebraic
dual bounds for shortest cycles below.

We define \textit{min-weight} ($S_w$) and \textit{min-length} ($S_l$)
cycles analogously to longest cycles. The following results parallel
Section~\ref{sec:extensions}.

\begin{lem}[Witness bounds for shortest cycles]
\label{lem:witness-shortest}
For any nonempty set $\mathcal{W}$ of cycles of $G$, $w(S_w) \leq \min\limits_{C \in
  \mathcal{W}} w(C)$ and $|S_l| \leq \min\limits_{C \in \mathcal{W}} |C|$.
\end{lem}

\begin{proof}
$S_w$ minimizes weight and $S_l$ minimizes length over all cycles of
$G$, including those in $\mathcal{W}$.
\end{proof}

\begin{lem}[Cycle mean bounds for shortest cycles]
\label{lem:shortest-mean-bounds}
For any min-weight or min-length cycle $S$,
\begin{equation}
  |S| \lambda_{min} \leq w(S) \leq |S| \lambda_{max}.
\end{equation}
\end{lem}

\begin{proof}
This is a direct application of Lemma~\ref{lem:basic-bounds} to the
specific cycle $S$.
\end{proof}

\label{sec:min-length-case}

Let $S_l$ be a min-length cycle and $\mathcal{C}_{max}$ be the set of
max-critical cycles $C_{max}$ found in $G$. By definition, the following
holds.

\begin{lem}[Min-length key inequality]
  \label{lem:min-length-key}
  If $\lambda_{max} \geq 0$, then
  \begin{equation*}
    w(S_l) \leq \min\limits_{C \in \mathcal{C}_{max}} w(C).
  \end{equation*}
\end{lem}

\begin{proof}
For any $C_{max}$, $w(S_l) \leq |S_l|\lambda_{max} \leq
|C_{max}|\lambda_{max} = w(C_{max})$, using $|S_l| \leq |C_{max}|$ and
$\lambda_{max} \geq 0$. The sign condition is necessary: with a
self-loop of weight $-1.5$ and a two-edge cycle whose edges weigh $-1$
each, $\lambda_{max} = -1$, $S_l$ is the self-loop, and $w(S_l) = -1.5
> -2 = w(C_{max})$.
\end{proof}

\begin{thm}[Bounds for min-length cycles]
  \label{thm:minlength-bounds}
\mbox{}\par
\begin{enumerate}
\item If $\lambda_{min} > 0$, then
  $|S_l| \leq \min\limits_{C \in \mathcal{C}_{max}} \lfloor w(C) / \lambda_{min} \rfloor$.
\item If $\lambda_{min} < 0$, the critical cycles yield no
  non-trivial lower bound on $|S_l|$.
\item If $\lambda_{min} = 0$, then
  $w(S_l) \geq 0$.
\end{enumerate}
\end{thm}

\begin{proof}
\mbox{}\par
\begin{itemize}
\item \textbf{Case 1 ($\lambda_{min} > 0$):} Then $\lambda_{max} > 0$,
  so Lemma~\ref{lem:min-length-key} applies and gives
  $|S_l|\lambda_{min} \leq w(S_l) \leq w(C_{max})$ for every $C_{max}$;
  divide by $\lambda_{min}$ and use the integrality of $|S_l|$.
\item \textbf{Case 2 ($\lambda_{min} < 0$):} If $\lambda_{max} \geq
  0$, combining Lemma~\ref{lem:min-length-key} with $w(S_l) \geq
  |S_l|\lambda_{min}$ gives $|S_l| \geq w(C_{max})/\lambda_{min}$, but
  the right-hand side is non-positive since $w(C_{max}) \geq 0$. If
  $\lambda_{max} < 0$, Lemma~\ref{lem:min-length-key} itself may fail,
  as its proof shows; in that example the would-be bound $|S_l| \geq
  w(C_{max})/\lambda_{min} = 4/3$ is violated by $|S_l| = 1$.
\item \textbf{Case 3 ($\lambda_{min} = 0$):} Every cycle has
  non-negative weight.
\end{itemize}
\end{proof}
